// Open/click tracking for Mail Merge for Gmail.
//   GET /mm-track/o?c=<campaign>&r=<recipient>          -> 1x1 GIF, logs an open
//   GET /mm-track/c?c=<campaign>&r=<recipient>&u=<url>  -> 302 to url, logs a click
//   GET /mm-track/stats?c=<campaign>                    -> per-recipient counts
// Campaign IDs are random UUIDs generated by the extension and act as the access key.
import { createClient } from 'npm:@supabase/supabase-js@2.45.4';

const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
const GIF = Uint8Array.from(atob('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'), ch => ch.charCodeAt(0));
const UUID = /^[0-9a-f-]{36}$/i;
const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json' };

Deno.serve(async req => {
  const url = new URL(req.url);
  const action = url.pathname.split('/').pop();
  const c = url.searchParams.get('c') ?? '';
  const r = (url.searchParams.get('r') ?? '').slice(0, 20);
  const valid = UUID.test(c) && r !== '';

  if (action === 'o') {
    if (valid) await db.from('mm_events').insert({ campaign: c, recipient: r, type: 'open' });
    return new Response(GIF, { headers: { 'Content-Type': 'image/gif', 'Cache-Control': 'no-store, max-age=0' } });
  }

  if (action === 'c') {
    const target = url.searchParams.get('u') ?? '';
    if (!/^https?:\/\//i.test(target)) return new Response('Invalid link', { status: 400 });
    if (valid) await db.from('mm_events').insert({ campaign: c, recipient: r, type: 'click', url: target.slice(0, 2000) });
    return Response.redirect(target, 302);
  }

  if (action === 'stats') {
    if (!UUID.test(c)) return new Response('{}', { status: 400, headers: cors });
    const out: Record<string, { opens: number; clicks: number; firstOpen?: string; urls: string[] }> = {};
    for (let from = 0; ; from += 1000) {
      const { data, error } = await db.from('mm_events').select('recipient,type,url,created_at')
        .eq('campaign', c).order('id').range(from, from + 999);
      if (error) return new Response(JSON.stringify({ error: error.message }), { status: 500, headers: cors });
      for (const e of data) {
        const s = out[e.recipient] ??= { opens: 0, clicks: 0, urls: [] };
        if (e.type === 'open') { s.opens++; s.firstOpen ??= e.created_at; }
        else { s.clicks++; if (e.url && !s.urls.includes(e.url)) s.urls.push(e.url); }
      }
      if (data.length < 1000) break;
    }
    return new Response(JSON.stringify(out), { headers: cors });
  }

  return new Response('Not found', { status: 404 });
});
